return "    .friend_brief {\n        playerid 1 : integer\n        name 2 : string #昵称\n        head_sculpture 3 : string #玩家头像\n        level 4 : integer #等级\n        class 5 : integer #学籍\n        fightpower 6 : integer #战力\n        lastlogin 7 : string # 最后离线时间 -1 表示在线\n        gift 8 : integer #已送出 已收到 已领取 分别对应第0-2三位\n        subscribe 9 : integer #订阅到期时间\n    }\n\n    get_friend_list 27000 {\n        request {\n            start 0 : integer\n            count 1 : integer\n        }\n        response {\n            result  0 : integer # 0 失败 1 成功\n            total   1 : integer #总数\n            list    2 : *friend_brief\n        }\n    }\n    get_black_list 27001 {\n        request {\n            start 0 : integer\n            count 1 : integer\n        }\n        response {\n            result  0 : integer # 0 失败 1 成功\n            total   1 : integer #总数\n            list    2 : *friend_brief\n        }\n    }\n    get_friend_application_list 27002 {\n        request {\n            start 0 : integer\n            count 1 : integer\n        }\n        response {\n            result  0 : integer # 0 失败 1 成功\n            total   1 : integer #总数\n            list    2 : *friend_brief\n        }\n    }\n    get_friend_recommend_list 27003 {\n        request {\n            refresh 0 : boolean # 是否刷新\n        }\n        response {\n            result  0 : integer # 0 失败 1 成功\n            list    2 : *friend_brief\n        }\n    }\n    #申请添加好友\n    apply_add_friend 27004 {\n        request {\n            playerid 0 : integer #要添加的好友id\n        }\n        response {\n            result  0 : integer # 0 失败 1 成功 2 当日申请达到上限 3 失败 已是好友 4 不能加自己为好友 5 对方申请已满\n        }\n    }\n\n    #处理好友申请\n    handle_friend_application 27005 {\n        request {\n            applicantid 0 : integer #申请者id\n            type 1 : integer # 1 接受 2 拒绝 3 忽略所有 4 接受所有\n        }\n        response {\n            result 0 : integer # 0 失败 1 成功 2 失败 自己好友上限  3 失败 对方好友上限 4 申请已失效,\n            successlist 2:*integer #成功添加的好友列表，目前仅用于接受所有申请的情况\n        }\n    }\n\n    #设置签名\n    set_signment 27006 {\n        request {\n            msg 0 : string #签名内容\n        }\n        response {\n            result 0 : integer # 0 失败 1 成功\n        }\n    }\n    #查询玩家\n    friend_search_player 27007 {\n        request {\n            playerid 0 : integer #玩家id\n        }\n        response {\n            result 0 : integer # 1 成功 2 玩家不存 3 不能查找自己\n            data 1 : friend_brief #查询玩家信息\n            relation 2 : integer #-1 没关系 1 好友 2 黑名单中 3 申请好友中 999 自己\n        }\n    }\n\n    .display_array_fight_girl {\n        modelid 0 : string\n        level 1 : integer\n        rank 2 : integer\n    }\n    .display_array {\n        fight_girls 0 : *display_array_fight_girl\n        fightpower 1 : integer\n    }\n    .player_display_data {\n        playerid 0 : integer\n        name 1 : string\n        signment 2 : string\n        level 3 : integer\n        class 4 : integer\n        head_sculpture 5 : string       #头像\n        medals 6 : *integer\n        array 7 : display_array\n        mainchapter 8 : string\n        rolenum 9 : integer\n        lastlogin 10 : string\n        grade 11 : integer #班级\n        arenascore 12 : integer #积分赛积分\n        areanrank 13 : integer #抢位赛排名\n        robot 14 : boolean\n        familyname 15 : string\n        bond 16 : *bond_data   #玩家羁绊信息\n        visitcardid 17 : integer # 名片卡id\n        visticardtime 18 : integer #名片卡到期时间\n        subscribe 19 : integer #订阅到期时间\n        star   20 : integer #星级\n    }\n    #查看玩家详情\n    get_player_display_data 27008 {\n        request {\n            playerid 0 : integer #玩家id\n        }\n        response {\n            result 0 : integer # 1 成功 2 玩家不存 \n            data 1 : player_display_data\n            relation 2 : integer # -1 没关系 1 好友 2 黑名单中 3 申请好友中 999 自己\n        }\n    }\n\n    \n    get_friend_data 27009 {\n        response {\n            maxfriend 0 : integer\n            maxpending 1 : integer\n            cansend 2 : boolean #可送礼物\n            canreceive 3 : boolean #可领取礼物\n            newpendding 4 : boolean #新的申请\n        }\n    }\n\n    #删除好友\n    delete_frined 27010 {\n        request {\n            playerid 0 : integer\n        }\n        response {\n            result 0 : integer # 0 失败 1 成功\n        }\n    }\n\n    #送礼收礼\n    friend_gift_opt 27011 {\n        request {\n            opt 0 : integer # 1 收取某个好友 2 送给某个好友 3 收取发送一键\n            playerid 1 : integer\n        }\n        response {\n            .info {\n                playerid 0 : integer\n                gift 1 : integer #已送出 已收到 已领取 分别对应第0-2三位\n            }\n            result 0 : integer # 1 成功 2 对方不是好友 3 没有赞可领取 4 领取上限\n            list 1 : *info #变化列表\n            items 2 : *item #物品\n        }\n    }\n\n    #查看某类阵容\n    get_someone_array 27012 {\n        request {\n            type 0 : integer #阵容类型 1 抢位赛进攻\n            playerid 1 : integer\n        }\n        response {\n            .posinfo {\n                modelid 0 : string\n                level 1 : integer\n                rank 2 : integer\n                hp 3 : integer\n                damage 4 : integer\n                fightpower 5 : integer\n                assistid 6 : integer\n                assistlv 7 : integer\n                assiststar 8 : integer\n                assisthclass 9 : integer\n                contract    10 : integer\n                overclock   11 : integer\n            }\n            .array {\n                array 0 : *posinfo #阵容信息\n                fightpower 1 : integer #总战斗力\n            }\n            result 0 : integer\n            arrays 1 : *array #阵容列表\n        }\n    }\n    \n    #获取玩家挂机阵容战斗数据\n    get_someone_array_fightdata 27013 {\n        request {\n            playerid 0 : integer\n        }\n        response {\n            result 0 : integer\n            playerdata 1 : *arena_totalfightdata\n            fightpower 2 : integer\n        }\n    }\n\n    #宿舍访问\n    get_someone_dorm_data 27014 {\n        request {\n            playerid 0 : integer\n        }\n        response {\n            .dress_data {\n                soulid 0 : integer\n                dress 1 : integer\n            }\n            result 0 : integer\n            dorm 1 : dormConfig\n            dresses 2 : *dress_data\n            award 3: boolean\n        }\n    }\n\n    #领取宿舍拜访奖励\n    get_dormvisit_award 27015 {\n        request {\n            playerid 0 : integer\n        }\n        response {\n            result 0 : integer # 1 成功 2 奖励不存在 3 奖励领取上限\n            gold 1 : integer\n            diamond 2 : integer\n            items 3 : *item\n        }\n    }\n\n    # 随机宿舍\n    get_rand_dorm 27016 {\n        response {\n            .dress_data {\n                soulid 0 : integer\n                dress 1 : integer\n            }\n            result 0 : integer  # 1 成功 2 暂无宿舍可访问\n            playerid 1 : integer\n            name 2 : string\n            head_sculpture 3 : integer\n            dorm 4 : dormConfig\n            dresses 5 : *dress_data\n        }\n    }\n"
